#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <vector>

using namespace std;

using ll = long long;

const int MAXN = 300001;
const int M = 60;

ll a[MAXN];
int pc[MAXN];

int getp2(ll x) {
    if (x <= 0) return -1;

    ll c = 1;
    int pw = 0;
    while (c < x && pw < M) {
        c *= 2;
        ++pw;
    }
    return c == x ? pw : -1;
}

bool check(vector<ll> bad, const vector<ll>& finishes) {
    if (finishes.size() < bad.size()) return false;

    sort(bad.begin(), bad.end());
    const size_t offset = finishes.size() - bad.size();

    for (size_t i = 0; i < bad.size(); ++i) {
        if (bad[i] >= 2 * finishes[offset + i]) return false;
    }
    return true;
}

void print(int l, int r) {
    for (int i = l; i <= r; ++i) {
        cout << i << ' ';
    }
    cout << '\n';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> bad;
    vector<ll> finishes;
    bad.reserve(2 * n);
    finishes.reserve(n);

    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        int p2 = getp2(a[i]);

        if (p2 != -1 && p2 < M) {
            ++pc[p2];
        } else {
            bad.push_back(a[i]);
        }
    }

    int cur = pc[0];

    for (int i = 1; i < M; ++i) {
        if (pc[i] > cur) {
            for (int j = cur; j < pc[i]; ++j) {
                bad.push_back(1LL << i);
            }
        }

        while (cur > pc[i]) {
            finishes.push_back(1LL << (i - 1));
            --cur;
        }
    }

    auto possible = [&](int remainingCount) {
        const int removedCount =
            static_cast<int>(finishes.size()) - remainingCount;

        if (bad.size() > static_cast<size_t>(remainingCount)) return false;

        size_t totalBad = bad.size();
        for (int i = 0; i < removedCount; ++i) {
            ll amount = finishes[i];

            if (amount > remainingCount ||
                totalBad > static_cast<size_t>(remainingCount - amount)) {
                return false;
            }

            totalBad += static_cast<size_t>(amount);
        }

        vector<ll> currentBad;
        currentBad.reserve(totalBad);
        currentBad.insert(currentBad.end(), bad.begin(), bad.end());

        for (int i = 0; i < removedCount; ++i) {
            for (ll value = 1; value <= finishes[i]; ++value) {
                currentBad.push_back(value);
            }
        }

        vector<ll> currentFinishes(
            finishes.begin() + removedCount,
            finishes.end()
        );

        return check(std::move(currentBad), currentFinishes);
    };

    int left = 0;
    int right = static_cast<int>(finishes.size()) + 1;

    while (left < right) {
        int middle = left + (right - left) / 2;

        if (possible(middle)) {
            right = middle;
        } else {
            left = middle + 1;
        }
    }

    if (left <= static_cast<int>(finishes.size())) {
        print(left, static_cast<int>(finishes.size()));
    } else {
        cout << -1 << '\n';
    }

    return 0;
}

