int getp2(ll x) {
    if (x <= 0 || (x & (x - 1)) != 0) return -1;

    int power = 0;
    while (x > 1) {
        x >>= 1;
        ++power;
    }
    return power;
}

bool check(vector<ll> values, const vector<ll>& targets) {
    if (targets.size() < values.size()) return false;

    sort(values.begin(), values.end());
    const size_t offset = targets.size() - values.size();

    for (size_t i = 0; i < values.size(); ++i) {
        if (values[i] >= 2 * targets[offset + i]) return false;
    }
    return true;
}

void printRange(int l, int r) {
