        cout << i << ' ';
    }
    cout << '\n';
}

bool feasible(int kept) {
    const int removed = static_cast<int>(finishes.size()) - kept;

    if (bad.size() > static_cast<size_t>(kept)) return false;

    ll available = kept - static_cast<ll>(bad.size());
    ll added = 0;

    for (int i = 0; i < removed; ++i) {
        if (finishes[i] > available - added) return false;
        added += finishes[i];
    }

    vector<ll> newBad;
    newBad.reserve(bad.size() + static_cast<size_t>(added));
    newBad.insert(newBad.end(), bad.begin(), bad.end());

    for (int i = 0; i < removed; ++i) {
        for (ll value = 1; value <= finishes[i]; ++value) {
            newBad.push_back(value);
        }
    }

    vector<ll> newFinishes(finishes.begin() + removed, finishes.end());
    return check(std::move(newBad), newFinishes);
}

